from pathlib import Path
import re
p=Path('app/src/main/java/com/ahmed/teacher/MainActivity.java')
t=p.read_text(encoding='utf-8')
if 'MODERN_UI_V2' in t:
    print('modern UI already applied'); raise SystemExit(0)
marker='    private void home(){'
helpers='''    // MODERN_UI_V2\n    private GradientDrawable bg(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}\n    private TextView modernLabel(String text,float size){TextView v=tv(text,size);v.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);v.setPadding(dp(16),dp(10),dp(16),dp(10));return v;}\n    private LinearLayout modernCard(String title,String sub,String icon,View.OnClickListener click){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(10),dp(14),dp(10));card.setBackground(bg(Color.WHITE,20));card.setElevation(dp(3));TextView a=modernLabel(icon+"  "+title,17);TextView b=modernLabel(sub,12);b.setTextColor(Color.rgb(95,105,130));card.addView(a);card.addView(b);card.setOnClickListener(click);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(78));lp.setMargins(dp(4),dp(5),dp(4),dp(5));card.setLayoutParams(lp);return card;}\n    private TextView stat(String big,String label){TextView v=tv(big+"\\n"+label,18);v.setBackground(bg(Color.WHITE,22));v.setPadding(dp(8),dp(14),dp(8),dp(14));v.setElevation(dp(2));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(92),1);lp.setMargins(dp(5),0,dp(5),0);v.setLayoutParams(lp);return v;}\n    private void addSpacer(int h){Space s=new Space(this);root.addView(s,new LinearLayout.LayoutParams(1,dp(h)));}\n\n'''
if marker not in t: raise SystemExit('home marker not found')
t=t.replace(marker,helpers+marker,1)
home='''    private void home(){\n        base("");\n        LinearLayout hero=new LinearLayout(this);hero.setOrientation(LinearLayout.VERTICAL);hero.setGravity(Gravity.CENTER);hero.setPadding(dp(18),dp(18),dp(18),dp(18));hero.setBackground(bg(Color.rgb(99,67,238),28));\n        TextView title=tv("تطبيق المعلم",28);title.setTextColor(Color.WHITE);hero.addView(title);\n        TextView sub=tv("إدارة التقييمات والحضور والبيانات بسهولة",14);sub.setTextColor(Color.WHITE);hero.addView(sub);\n        TextView welcome=tv("مرحبًا بك 👋",18);welcome.setTextColor(Color.WHITE);hero.addView(welcome);\n        TextView owner=tv("© Ahmed Mostafa Abonajy  •  إصدار 2026",12);owner.setTextColor(Color.WHITE);hero.addView(owner);\n        root.addView(hero,new LinearLayout.LayoutParams(-1,dp(180))); addSpacer(12);\n        LinearLayout stats=new LinearLayout(this);stats.setOrientation(LinearLayout.HORIZONTAL);stats.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);stats.addView(stat("3","صفوف"));stats.addView(stat("9","فصول"));stats.addView(stat("+50","طالب/فصل"));root.addView(stats);\n        section("لوحة التحكم");\n        root.addView(modernCard("التقييم الأسبوعي","تسجيل الدرجات بسرعة مع الحفظ التلقائي","📝",v->classes(4)));\n        root.addView(modernCard("الحضور والغياب","علامة ✓ للغائب والباقي حضور","✅",v->classes(4)));\n        root.addView(modernCard("التقييم الشهري والاختبارات","الشهر الأول والثاني والمجموع تلقائيًا","📊",v->monthly()));\n        root.addView(modernCard("التقارير","عرض ومراجعة درجات الطلاب","📈",v->monthly()));\n        section("أدوات سريعة لتوفير الوقت");\n        root.addView(modernCard("إدارة الطلاب","إضافة • حذف • استيراد Excel • تعديل الأسماء","👥",v->classes(4)));\n        root.addView(modernCard("تصدير Excel","تصدير الفصل أو كل البيانات","📤",v->exportExcel()));\n        root.addView(modernCard("الطباعة","طباعة كشف التقييم والحضور","🖨",v->printReport()));\n        root.addView(modernCard("بيانات المدرسة","اسم المدرسة • المعلم • المادة","🏫",v->schoolData()));\n        root.addView(modernCard("قفل التقييم","قفل الأسبوع بعد الانتهاء لمنع التعديل بالخطأ","🔒",v->classes(4)));\n        root.addView(modernCard("مساعد الحصة","اختصارات سريعة للوصول للصف والتقييم","⚡",v->classes(4)));\n        addSpacer(8); TextView foot=tv("صُمم لتوفير وقت المعلم داخل الحصة",12);foot.setTextColor(Color.GRAY);root.addView(foot);\n    }\n'''
t,n=re.subn(r'    private void home\(\)\{.*?(?=\n    private void schoolData\(\))',home,t,count=1,flags=re.S)
if n!=1: raise SystemExit('home replace failed')
assessment='''    private void assessment(){\n        base("الصف "+grade+" - الفصل "+cls);\n        TextView head=tv("التقييم الأسبوعي",22);head.setTextColor(Color.rgb(65,45,180));root.addView(head); root.addView(tv("📅 "+weekTitle(),16));\n        root.addView(btn(weekDate().isEmpty()?"📅 تحديد تاريخ التقييم":"✏️ تغيير تاريخ التقييم",v->chooseWeekDate()));\n        LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);Button next=new Button(this);next.setText("الأسبوع التالي ▶");next.setAllCaps(false);next.setOnClickListener(v->goNextWeek());Button prev=new Button(this);prev.setText("◀ الأسبوع السابق");prev.setAllCaps(false);prev.setOnClickListener(v->goPreviousWeek());nav.addView(next,new LinearLayout.LayoutParams(0,dp(52),1));nav.addView(prev,new LinearLayout.LayoutParams(0,dp(52),1));root.addView(nav);\n        boolean locked=isWeekLocked(); TextView status=tv(locked?"🔒 التقييم مقفول":"🟢 التقييم مفتوح • الحفظ تلقائي",14);status.setTextColor(locked?Color.rgb(190,70,70):Color.rgb(30,150,80));root.addView(status);\n        LinearLayout hdr=new LinearLayout(this);hdr.setOrientation(LinearLayout.HORIZONTAL);hdr.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);hdr.setBackground(bg(Color.rgb(239,235,255),14));String[] labels={"اسم الطالب","سلوك 5","واجب 5","نشاط 5","شفوي 5","نسخ 5","المجموع"};for(String s:labels){TextView h=tv(s,12);h.setPadding(dp(4),dp(10),dp(4),dp(10));hdr.addView(h,new LinearLayout.LayoutParams(0,dp(58),s.equals("اسم الطالب")?2.2f:1));}root.addView(hdr);\n        for(int row=0;row<names.size();row++){final String student=names.get(row);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);line.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);line.setPadding(dp(2),dp(3),dp(2),dp(3));line.setBackground(bg(row%2==0?Color.WHITE:Color.rgb(248,249,253),12));TextView name=tv((row+1)+". "+student,12);name.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);line.addView(name,new LinearLayout.LayoutParams(0,dp(64),2.2f));\n            String[] parts={"beh","hw","activity","oral","copy"};ArrayList<EditText> fields=new ArrayList<>();\n            for(int i=0;i<parts.length;i++){final String part=parts[i];EditText e=field("",String.valueOf(savedScore(student,week,part,5)));e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);e.setTextSize(15);e.setGravity(Gravity.CENTER);e.setSingleLine(true);e.setSelectAllOnFocus(true);e.setEnabled(!locked);e.setImeOptions(i==parts.length-1?android.view.inputmethod.EditorInfo.IME_ACTION_DONE:android.view.inputmethod.EditorInfo.IME_ACTION_NEXT);e.setBackground(bg(Color.WHITE,10));\n                e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){try{int v=s.length()==0?0:Integer.parseInt(s.toString());saveScore(student,week,part,v);}catch(Exception ignored){}}public void afterTextChanged(Editable e){}});fields.add(e);line.addView(e,new LinearLayout.LayoutParams(0,dp(56),1));}\n            TextView total=tv("0 / 25",12);total.setTextColor(Color.rgb(30,145,80));line.addView(total,new LinearLayout.LayoutParams(0,dp(64),1));Runnable updateTotal=()->{int sum=0;for(String p:parts)sum+=savedScore(student,week,p,5);total.setText(sum+" / 25");};updateTotal.run();\n            for(int i=0;i<fields.size();i++){final int idx=i;fields.get(i).setOnEditorActionListener((v,a,event)->{if(a==android.view.inputmethod.EditorInfo.IME_ACTION_NEXT||a==android.view.inputmethod.EditorInfo.IME_ACTION_DONE){if(idx+1<fields.size()){fields.get(idx+1).requestFocus();fields.get(idx+1).selectAll();}else{updateTotal.run();v.clearFocus();}return true;}return false;});fields.get(i).setOnFocusChangeListener((v,has)->{if(!has)updateTotal.run();});}\n            CheckBox absent=new CheckBox(this);absent.setText("غائب");absent.setChecked(isAbsent(student,week));absent.setEnabled(!locked);absent.setOnCheckedChangeListener((b,c)->saveAbsent(student,week,c));line.addView(absent,new LinearLayout.LayoutParams(0,dp(50),.8f));root.addView(line);\n        }\n        root.addView(btn("🔒 قفل التقييم الأسبوعي",v->{if(!isWeekLocked()){setWeekLocked(true);Toast.makeText(this,"تم قفل "+week,Toast.LENGTH_SHORT).show();goNextWeek();}else Toast.makeText(this,"التقييم مقفول بالفعل",Toast.LENGTH_SHORT).show();}));root.addView(btn("🔓 فتح التقييم للتعديل",v->{setWeekLocked(false);assessment();}));root.addView(btn("➕ إضافة طالب جديد",v->addStudentDialog()));root.addView(btn("🗑 حذف طالب",v->deleteStudentDialog()));root.addView(btn("🗑 حذف جميع الطلاب",v->deleteAllStudentsDialog()));root.addView(btn("📤 تصدير الفصل إلى Excel",v->exportExcel()));root.addView(btn("🖨 طباعة التقييم",v->printReport()));root.addView(btn("⬅ العودة للفصل",v->open(cls)));\n    }\n'''
t,n=re.subn(r'    private void assessment\(\)\{.*?(?=\n    private void monthly\()',assessment,t,count=1,flags=re.S)
if n!=1: raise SystemExit('assessment replace failed')
p.write_text(t,encoding='utf-8');print('modern UI and fast weekly grading applied')
